Rules.InvariantScript:
UpdateContext(
    {
        var_visibleFormContatos: true,
        var_acaoFormContatos: "Cadastrar contato",
        var_dadosContatos: Blank()
    }
);
NewForm(FormCadastrarContato)

ControlPropertyState.AutoRuleBindingString:
ResetForm(FormCheckREA);
NewForm(FormCheckREA);
Clear(col_checkRespostasREA);
ClearCollect(
    col_checkRespostasREA,
    ForAll(
        col_checkListREAitensAberto,
        {
            ID: ThisRecord.ID_item_classe,
            Resposta: ThisRecord.Resposta,
            Descricao: ThisRecord.Descricao,
            Foto: ThisRecord.Foto,
            //CCrLogo;
            Status: "Solucionado"
        }
    )
);
UpdateContext(
    {
        var_visibleFormCKREA: true,
        var_formTitle: "Cadastrar"
        //;var_visibleMain: false
    }
)

Rules.InvariantScript:
UpdateContext(
    {
        var_visibleFormContatos: true,
        var_acaoFormContatos: "Editar contato",
        var_dadosContatos: GalleryContatos_2.Selected
    }
);
EditForm(FormCadastrarContato)

ControlPropertyState.AutoRuleBindingString:
EditForm(FormCheckREAedit);
ClearCollect(
    col_checkRespostasREAedit,
    ForAll(
        Filter(
            tbl_Checklist_REA_objeto,
            ID_checkList = GalleryCKREA.Selected.ID
        ),
        {
            ID: ThisRecord.ID_item_classe,
            Resposta: ThisRecord.Resposta,
            Descricao: ThisRecord.Descricao,
            Foto: ThisRecord.Foto.Medium
        }
    )
);
UpdateContext(
    {
        var_visibleREAedit: true,
        var_visibleAnexoVE: false,
        var_formTitle: "Editar"
        //var_visibleMain: false
    }
)

Rules.InvariantScript:
UpdateContext(
    {
        var_visibleFormContatos: true,
        var_acaoFormContatos: "Editar contato",
        var_dadosContatos: GalleryContatos_2.Selected
    }
);
ViewForm(FormCadastrarContato)

ControlPropertyState.AutoRuleBindingString:
ViewForm(FormCheckREA);
UpdateContext(
    {
        var_detalhesCKREA: GalleryCKREA.Selected,
        var_visibleCKREAdetalhes: true,
        var_formTitle: "Detalhes"
        //var_visibleMain: false
    }
);
ClearCollect(
    col_detalhesREAitens,
    Filter(
        tbl_Checklist_REA_objeto,
        ID_checkList = GalleryCKREA.Selected.ID
    )
)

Rules.InvariantScript:
DisplayMode.Edit

/*If(
    GalleryCKREA.Selected.'Criado por'.DisplayName = varNomeUser;
    DisplayMode.Edit;
    DisplayMode.View
)*/

ControlPropertyState.AutoRuleBindingString:
UpdateContext(
    {
        var_visibleExcluir: true,
        var_REAEditar: GalleryCKREA.Selected,
        var_visibleMain: false
    }
)

With(
    {
        baseREA: Filter(
            Sort(
                tbl_Checklist_REA_base,
                ID,
                SortOrder.Descending
            ),
            ID_modulo = var_idModulo && (varPerfilUser <> "Base" || Aeroporto = cmbCKREAaeroporto.Selected.Result)
        )
    },
    ClearCollect(
        col_checkListREA,
        Sort(
            baseREA,
            ID,
            SortOrder.Descending
        )
    )
);

Rules.InvariantScript:
UpdateContext({var_visibleExcluirContato: false});
RemoveIf(
    tbl_contatos_entidades,
    ID = var_dadosContatos.ID
);
Notify(
    "Contato excluido com sucesso!",
    NotificationType.Warning
)
